// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        vm.prank(address(0));
        c.transferOwnership(caller);

        address attacker = address(uint160(uint256(keccak256(abi.encodePacked(caller, newOwner, block.timestamp)))));
        vm.assume(attacker != caller);

        address before = c.owner();

        vm.prank(attacker);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(c.owner() == before);
    }
}
